package equivalent;

import metadata.BehavioralDifference;
import metadata.DifferenceType;

import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertTrue;

class ClonePair6187DifferenceFindingTest {

    private final ClonePair6187 subject = new ClonePair6187();

    /**
     * Generated by Claude Code (Claude Fable 5.1).
     * Difference type: return_value.
     * Difference manifestation: the methods return different values.
     */
    @Test
    @BehavioralDifference(DifferenceType.RETURN_VALUE)
    void methodsDisagreeOnEqualSizedListsWithDuplicateElements() {
        // method1 only checks that every element of the first list occurs in the second list,
        // whereas method2 compares the two lists as sets.
        List<String> repeated = new ArrayList<>(List.of("a", "a"));
        List<String> distinct = new ArrayList<>(List.of("a", "b"));

        assertTrue(subject.method1(repeated, distinct));
        assertFalse(subject.method2(repeated, distinct));
    }
}
